#!/usr/bin/env python3
"""Render offline private organizer preview. Do not publish without access review."""
import json, html, sys
from pathlib import Path
if len(sys.argv)!=4: raise SystemExit('Usage: build_dashboard.py graph.json opportunities.json output.html')
graph=json.loads(Path(sys.argv[1]).read_text());out=json.loads(Path(sys.argv[2]).read_text())
projects=[n for n in graph['nodes'] if n.get('type')=='Project']
ops=out['opportunities'];labels={'event_sponsorship':'Sponsoring de meetup','general_meetup':'Meetup généraliste','themed_meetup':'Meetup thématique','workshop':'Workshop','dinner':'Dîner technique','hackathon':'Hackathon'}
rows=[]
for o in ops:
 refs=[next((p['name'] for p in projects if p['id']==pid),pid) for pid in o['project_ids']]
 sources=[f'<a href="{html.escape(x,quote=True)}" rel="noopener noreferrer" target="_blank">Source</a>' for x in o['evidence'] if x.startswith('https://')]
 rows.append(f'<article class="card" data-kind="{html.escape(o["type"])}"><header><span class="badge">{html.escape(labels.get(o["type"],o["type"]))}</span><span class="rank">Priorité indicative {o["priority"]}</span></header><h3>{html.escape(o["title"])}</h3><p>{html.escape(o["why"])}</p><p class="muted">Projets : {html.escape(" · ".join(refs))}</p><footer>{" · ".join(sources) if sources else "Sources : voir graphe"}</footer></article>')
options=''.join(f'<option value="{html.escape(k)}">{html.escape(v)}</option>' for k,v in labels.items())
body='\n'.join(rows)
html_doc='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mes opportunités — AI Tinkerers</title><style>
:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#0f1424;color:#f4f6ff}*{box-sizing:border-box}body{margin:0 auto;max-width:1180px;padding:30px 20px}h1{font-size:clamp(28px,4vw,46px);margin:10px 0}p{line-height:1.6}small,.muted{color:#a7b3d0}a{color:#b0bcff}header{display:flex;justify-content:space-between;gap:12px;align-items:center}.hero{border:1px solid #3d4c6d;border-radius:20px;background:linear-gradient(120deg,#1e2944,#151d32);padding:25px;margin:22px 0}.badge{background:#28365a;border-radius:100px;padding:7px 12px;color:#c2cbff;font-size:12px}.rank{font-size:12px;color:#afbad2}.stats{display:flex;flex-wrap:wrap;gap:12px}.stat{background:#202a41;border:1px solid #34415b;padding:14px 20px;border-radius:14px}.stat strong{font-size:27px;display:block}.controls{display:flex;flex-wrap:wrap;gap:12px;margin:25px 0}input,select{padding:13px;background:#1c263d;color:white;border:1px solid #425171;border-radius:12px;font-size:15px}input{flex:1;min-width:220px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(295px,1fr));gap:14px}.card{background:#19243a;border:1px solid #354560;border-radius:18px;padding:20px}.card h3{margin-bottom:4px}.card footer{font-size:13px;margin-top:16px}.notice{padding:14px;border-left:3px solid #ffbe98;background:#2c2930;border-radius:9px}.empty{display:none}</style></head><body>
<small>ESPACE PERSONNEL · PROTOTYPE LOCAL · AUCUN CONTACT AUTOMATIQUE</small><h1>Mes opportunités AI Tinkerers</h1><p>Transformer les projets techniques en décisions de sponsoring et d'événements. Les priorités sont indicatives, non prédictives.</p>
<section class="hero"><small>PROCHAINE ACTION À QUALIFIER</small><h2>Identifier les fournisseurs des technologies utilisées</h2><p>Des projets réels utilisent des outils identifiés. Vérifier d'abord les relations sponsors existantes avant toute proposition. Aucune note individuelle n'est disponible pour recommander un workshop.</p><div class="stats"><div class="stat"><strong>__PROJECTS__</strong>projets documentés</div><div class="stat"><strong>__OPPS__</strong>pistes d'activation</div><div class="stat"><strong>0</strong>notes de projets vérifiées</div></div></section>
<p class="notice">Cette vue est interne, constituée d'un échantillon : Lima et deux démos mondiales. Pas de synchronisation temps réel avec Gmail, l'API ou le Site publié. Un projet ou un prospect évoqué n'est pas un événement confirmé.</p>
<div class="controls"><input id="q" placeholder="Rechercher un projet, une technologie ou une opportunité" aria-label="Recherche"><select id="kind" aria-label="Filtre format"><option value="">Tous les formats</option>__OPTIONS__</select></div><div class="cards" id="cards">__CARDS__</div><p id="empty" class="empty">Aucune opportunité pour ce filtre.</p>
<script>const q=document.getElementById('q'),k=document.getElementById('kind');function filter(){let count=0;for(const card of document.querySelectorAll('.card')){let show=card.textContent.toLowerCase().includes(q.value.toLowerCase())&&(!k.value||card.dataset.kind===k.value);card.hidden=!show;if(show)count++;}document.getElementById('empty').style.display=count?'none':'block'}q.addEventListener('input',filter);k.addEventListener('change',filter);</script></body></html>'''
html_doc=html_doc.replace('__PROJECTS__',str(len(projects))).replace('__OPPS__',str(len(ops))).replace('__OPTIONS__',options).replace('__CARDS__',body)
Path(sys.argv[3]).write_text(html_doc)
print('Wrote',sys.argv[3])